  return `<header><div class="header-left"><a class="brand" href="/dashboard">🐺 Cerberus <span class="muted">Admin Dashboard</span></a><nav class="navlinks"><a class="${active === "moderation" ? "active" : ""}" href="/dashboard">Moderation</a><a class="${active === "logging" ? "active" : ""}" href="/dashboard/logging">Event Logging</a><a class="${active === "notes" ? "active" : ""}" href="/dashboard/notes">Notes</a><a class="${active === "tickets" ? "active" : ""}" href="/dashboard/tickets">Tickets</a><a class="${active === "transcripts" ? "active" : ""}" href="/dashboard/transcripts">Transcripts</a><a class="${active === "verification" ? "active" : ""}" href="/dashboard/verification">Verification</a>${globalAdmin ? `<a class="${active === "developer" ? "active" : ""}" href="/dashboard/developer">Developer</a>` : ""}</nav></div><button onclick="logout()">Logout</button></header>`;
