function dashboardScript(): string {
  return `<script>const state={guild:null};const esc=function(s){return String(s||'').replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})};async function api(path){const r=await fetch(path);if(!r.ok){let d={};try{d=await r.json()}catch{}throw new Error(d.error||'Request failed')}return r.json()}async function getGuilds(){const d=await api('/api/guilds');if(d.globalAdmin&&!document.querySelector('.navlinks a[href="/dashboard/developer"]')){const n=document.querySelector('.navlinks');if(n)n.insertAdjacentHTML('beforeend','<a href="/dashboard/developer">Developer</a>')};if(!d.guilds.length)throw new Error('No Discord servers where you have Administrator access were found.');if(!state.guild)state.guild=d.guilds[0].id;return d.guilds}function guildSidebar(guilds){return '<aside class="panel"><h3>Servers</h3>'+guilds.map(function(g){return '<div class="guild '+(g.id===state.guild?'active':'')+'" onclick="selectGuild(\\''+g.id+'\\')">'+esc(g.name)+'</div>'}).join('')+'</aside>'}function selectGuild(id){state.guild=id;loadPage()}async function logout(){await fetch('/logout',{method:'POST'});location.href='/'};</script>`;
}

